/** The text that marks a file as generated; the generator deletes only files that carry it. */
export const GENERATED_MARK = "Generated by @media/commands";

/** The note at the top of every generated file, one entry per line of that file's comment. */
export const GENERATED_NOTE = [
  `${GENERATED_MARK} from packages/commands/src. Do not edit: change the command`,
  "list and run `pnpm --filter @media/commands generate`.",
] as const;
